#!/usr/bin/env bash
# Writes the Homebrew formula for whk to stdout, from a release's version and
# its checksums.txt (as the CLI Release workflow publishes it).
#
#   .github/scripts/homebrew-formula.sh 1.8.0 checksums.txt > whk.rb
#
# The tap (kroqdotdev/homebrew-tap) keeps the formula as whk.rb at its root.
# Each archive holds the whk binary at its top level.
set -euo pipefail

version="${1:?usage: homebrew-formula.sh <version without v> <checksums.txt>}"
checksums="${2:?usage: homebrew-formula.sh <version without v> <checksums.txt>}"
version="${version#v}"

if ! [[ "$version" =~ ^[0-9]+\.[0-9]+\.[0-9]+([-.][0-9A-Za-z.]+)?$ ]]; then
  echo "not a version: $version" >&2
  exit 1
fi

base="https://github.com/kroqdotdev/webhooks-cc/releases/download/v${version}"

sha() {
  local name="whk-v${version}-$1.tar.gz"
  local sum
  sum="$(awk -v n="$name" '$2 == n { print $1 }' "$checksums")"
  if ! [[ "$sum" =~ ^[0-9a-f]{64}$ ]]; then
    echo "no sha256 for $name in $checksums" >&2
    exit 1
  fi
  echo "$sum"
}

mac_arm="$(sha aarch64-apple-darwin)"
mac_intel="$(sha x86_64-apple-darwin)"
linux_arm="$(sha aarch64-unknown-linux-gnu)"
linux_intel="$(sha x86_64-unknown-linux-gnu)"

cat <<RUBY
# typed: false
# frozen_string_literal: true

# Generated by .github/scripts/homebrew-formula.sh in kroqdotdev/webhooks-cc
# on each CLI release. Do not edit by hand.
class Whk < Formula
  desc "CLI for webhooks.cc: capture, inspect, forward and replay webhooks and email"
  homepage "https://webhooks.cc"
  version "${version}"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "${base}/whk-v${version}-aarch64-apple-darwin.tar.gz"
      sha256 "${mac_arm}"
    else
      url "${base}/whk-v${version}-x86_64-apple-darwin.tar.gz"
      sha256 "${mac_intel}"
    end
  end

  on_linux do
    if Hardware::CPU.arm? && Hardware::CPU.is_64_bit?
      url "${base}/whk-v${version}-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "${linux_arm}"
    elsif Hardware::CPU.intel? && Hardware::CPU.is_64_bit?
      url "${base}/whk-v${version}-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "${linux_intel}"
    else
      odie "whk has builds for 64-bit Intel and ARM Linux only; see https://webhooks.cc/installation"
    end
  end

  def install
    bin.install "whk"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/whk --version")
  end
end
RUBY
